import { fireEvent, render, screen, cleanup } from '@testing-library/react';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { AgentChatWithHistory } from './AgentChatWithHistory';
vi.mock('./Settings', () => ({ useSettings: () => ({ settings: { preferences: { defaultProvider: 'alibaba' } } }) }));
vi.mock('./AgentChat', () => ({ AgentChat: ({ existingMessages }: { existingMessages: { content: string }[] }) => <div data-testid="actual-chat-messages">{existingMessages.map(m => m.content).join('|')}</div> }));
const key = 'cvf_chat_history';
beforeEach(() => {
  localStorage.clear();
  const when = new Date().toISOString();
  localStorage.setItem(key, JSON.stringify({ activeSessionId: 'saved-A', sessions: ['A', 'B'].map(id => ({ id: `saved-${id}`, title: `Saved ${id}`, provider: 'alibaba', createdAt: when, updatedAt: when, metadata: { messageCount: 1 }, messages: [{ id: `msg-${id}`, role: 'user', content: `body-${id}`, timestamp: when }] })) }));
});
afterEach(() => { cleanup(); localStorage.clear(); });
it('new chat appears in the actual sidebar and can be selected without reopening', () => {
  render(<AgentChatWithHistory />);
  expect(screen.getByTestId('actual-chat-messages').textContent).toBe('body-A');
  fireEvent.click(screen.getByRole('button', { name: /New Chat/ }));
  expect(JSON.parse(localStorage.getItem(key)!).sessions).toHaveLength(3);
  expect(screen.getAllByTitle('Delete')).toHaveLength(3);
});
it('deleting active history changes the actual chat and cannot resurrect deleted content', () => {
  render(<AgentChatWithHistory />);
  expect(screen.getByTestId('actual-chat-messages').textContent).toBe('body-A');
  fireEvent.click(screen.getAllByTitle('Delete')[0]);
  expect(JSON.parse(localStorage.getItem(key)!).sessions.map((s: { id: string }) => s.id)).toEqual(['saved-B']);
  const bodyAfterDelete = screen.getByTestId('actual-chat-messages').textContent;
  fireEvent.click(screen.getByRole('button', { name: /New Chat/ }));
  const idsAfterNew = JSON.parse(localStorage.getItem(key)!).sessions.map((s: { id: string }) => s.id);
  expect({ bodyAfterDelete, resurrected: idsAfterNew.includes('saved-A') }).toEqual({ bodyAfterDelete: 'body-B', resurrected: false });
});
